def _checked_multi_indices(indices: Sequence[int], size: int) -> list[int]:
    if isinstance(indices, (bytes, bytearray, str)) or not isinstance(indices, Sequence):
        raise TypeError("indices must be a sequence of integers")
    items = list(indices)  # copy: inputs are never mutated
    if not items:
        raise ValueError("indices must not be empty")
    previous: int | None = None
    for position, index in enumerate(items):
        if not isinstance(index, int) or isinstance(index, bool):
            raise TypeError(f"indices[{position}] must be an integer")
        if previous is not None and index <= previous:
            raise ValueError("indices must be strictly increasing without duplicates")
        previous = index
    for index in items:
        if not 0 <= index < size:
            raise IndexError(f"index {index} out of range for {size} leaves")
    return items


def prove_multi_inclusion(leaves: Sequence[bytes], indices: Sequence[int]) -> MerkleMultiProof:
    """Build a compact :class:`MerkleMultiProof` for the leaves at ``indices``.

    ``indices`` must be non-empty, strictly increasing and duplicate-free.
    The proof is deterministic and minimal: when every leaf is proven,
    ``siblings`` is empty.
    """
    items = _checked_leaves(leaves)
    positions = _checked_multi_indices(indices, len(items))
    level = [_leaf_digest(leaf) for leaf in items]
    siblings: list[bytes] = []
    known = positions
    while len(level) > 1:
        size = len(level)
        known_set = set(known)
        for position in known:  # ascending: siblings collected left to right
            sibling = position ^ 1
            if sibling in known_set:
                continue  # sibling is proven too, nothing to collect
            if position == size - 1 and size % 2 == 1:
                continue  # odd last node duplicates itself
            siblings.append(level[sibling])
        if size % 2 == 1:
            level = level + [level[-1]]
        level = [
            _node_digest(level[offset], level[offset + 1])
            for offset in range(0, len(level), 2)
        ]
        known = sorted({position // 2 for position in known})
    return MerkleMultiProof(
        leaf_count=len(items),
        indices=tuple(positions),
        siblings=tuple(siblings),
    )


def verify_multi_inclusion(
    entries: Sequence[tuple[int, bytes]],
    proof: MerkleMultiProof,
    root: bytes,
) -> bool:
    """Check ``entries`` against ``proof`` and Merkle ``root`` without the full leaf set.

    ``entries`` holds one ``(index, leaf)`` pair per entry, in the exact order
    of ``proof.indices``. Type errors raise :class:`TypeError`; empty,
    misordered, out-of-range, miscounted or tampered inputs return False.
    """
    _check_bytes(root, "root")
    if not isinstance(proof, MerkleMultiProof):
        raise TypeError("proof must be a MerkleMultiProof")
    if not isinstance(proof.leaf_count, int) or isinstance(proof.leaf_count, bool):
        raise TypeError("proof leaf_count must be an integer")
    if not isinstance(proof.indices, tuple):
        raise TypeError("proof indices must be a tuple of integers")
    for index in proof.indices:
        if not isinstance(index, int) or isinstance(index, bool):
            raise TypeError("proof indices must be a tuple of integers")
    if not isinstance(proof.siblings, tuple):
        raise TypeError("proof siblings must be a tuple of bytes")
    for sibling in proof.siblings:
        _check_bytes(sibling, "proof sibling")
    if isinstance(entries, (bytes, bytearray, str)) or not isinstance(entries, Sequence):
        raise TypeError("entries must be a sequence of (index, leaf) pairs")
    pairs: list[tuple[int, bytes]] = []
    for position, entry in enumerate(entries):
        if not isinstance(entry, (tuple, list)) or len(entry) != 2:
            raise TypeError(f"entries[{position}] must be an (index, leaf) pair")
        index, leaf = entry
        if not isinstance(index, int) or isinstance(index, bool):
            raise TypeError(f"entries[{position}] index must be an integer")
        if not isinstance(leaf, bytes):
            raise TypeError(f"entries[{position}] leaf must be bytes")
        pairs.append((index, leaf))
    if proof.leaf_count < 1:
        return False
    if not proof.indices:
        return False
    if any(
        later <= earlier for earlier, later in zip(proof.indices, proof.indices[1:])
    ):
        return False  # duplicates or out-of-order indices
    if proof.indices[0] < 0 or proof.indices[-1] >= proof.leaf_count:
        return False
    if not pairs:
        return False
    if tuple(index for index, _ in pairs) != proof.indices:
        return False
    if len(root) != _MERKLE_DIGEST_SIZE:
        return False
    if any(len(sibling) != _MERKLE_DIGEST_SIZE for sibling in proof.siblings):
        return False
    known = {index: _leaf_digest(leaf) for index, leaf in pairs}
    size = proof.leaf_count
    siblings = proof.siblings
    cursor = 0
    while size > 1:
        next_known: dict[int, bytes] = {}
        for position in sorted(known):
            sibling = position ^ 1
            if sibling in known:
                sibling_digest = known[sibling]
            elif position == size - 1 and size % 2 == 1:
                sibling_digest = known[position]  # odd last node duplicates itself
            else:
                if cursor >= len(siblings):
                    return False  # proof ran out of siblings
                sibling_digest = siblings[cursor]
                cursor += 1
            if position % 2 == 0:
                digest = _node_digest(known[position], sibling_digest)
            else:
                digest = _node_digest(sibling_digest, known[position])
            next_known[position // 2] = digest
        known = next_known
        size = (size + 1) // 2
    if cursor != len(siblings):
        return False  # every sibling must be consumed
    return hmac.compare_digest(known[0], root)


# ---------------------------------------------------------------------------
# Canonical transport envelope for Merkle multi-inclusion proofs
#
# A MerkleMultiProofBundle freezes the three arguments of
# verify_multi_inclusion (root, proof, entries) into one immutable object
# that can be encoded into a self-contained byte string, shipped across
# processes and verified again after decoding. It composes only the generic
# wire primitives above under its own magic and format version, so a
# multi-proof envelope can never be mistaken for a region proof envelope.
# Encoding is a pure function of the field values: the same bundle always
# maps to the same bytes, and decoding those bytes rebuilds an equal
# bundle.

_MERKLE_MULTI_BUNDLE_MAGIC = b"zmmp"
_MERKLE_MULTI_BUNDLE_VERSION = 1


@dataclass(frozen=True)
class MerkleMultiProofBundle:
    """A versioned, canonical binary envelope for one multi-inclusion proof.

    Fields, in the fixed wire order: ``root`` (``bytes``), ``proof``
    (:class:`MerkleMultiProof`) and ``entries``
    (``tuple[tuple[int, bytes], ...]`` of ``(index, leaf)`` pairs in the
    exact order of ``proof.indices``). Bundles are positional construction
    arguments, compare by value and are immutable; construction performs no
    validation — use :func:`encode_merkle_multi_proof_bundle` /
    :func:`verify_merkle_multi_proof_bundle` to check.
    """

    root: bytes
    proof: MerkleMultiProof
    entries: tuple[tuple[int, bytes], ...]


def _check_merkle_multi_bundle_proof_types(proof: object) -> None:
    """Type-check a bundle ``proof`` field (values are decided elsewhere)."""
    if not isinstance(proof, MerkleMultiProof):
        raise TypeError("proof must be a MerkleMultiProof")
    if not isinstance(proof.leaf_count, int) or isinstance(proof.leaf_count, bool):
        raise TypeError("proof leaf_count must be an integer")
    if not isinstance(proof.indices, tuple):
        raise TypeError("proof indices must be a tuple of integers")
    for index in proof.indices:
        if not isinstance(index, int) or isinstance(index, bool):
            raise TypeError("proof indices must be a tuple of integers")
    if not isinstance(proof.siblings, tuple):
        raise TypeError("proof siblings must be a tuple of bytes")
    for sibling in proof.siblings:
        _check_bytes(sibling, "proof sibling")


def _check_merkle_multi_bundle_entries_types(entries: object) -> None:
    """Type-check a bundle ``entries`` field (values are decided elsewhere)."""
    if not isinstance(entries, tuple):
        raise TypeError("entries must be a tuple of (index, leaf) pairs")
    for position, entry in enumerate(entries):
        if not isinstance(entry, tuple) or len(entry) != 2:
            raise TypeError(f"entries[{position}] must be an (index, leaf) pair")
        index, leaf = entry
        if not isinstance(index, int) or isinstance(index, bool):
            raise TypeError(f"entries[{position}] index must be an integer")
        if not isinstance(leaf, bytes):
            raise TypeError(f"entries[{position}] leaf must be bytes")


def encode_merkle_multi_proof_bundle(bundle: MerkleMultiProofBundle) -> bytes:
    """Encode a :class:`MerkleMultiProofBundle` into its canonical byte envelope.

    The same bundle object always encodes to the same byte string. The
    output starts with the four-byte magic ``b"zmmp"`` and a one-byte
    format version, followed by the three fields in fixed order
    (``root``, ``proof``, ``entries``); each item is length-prefixed with
    a four-byte big-endian header. The proof body is the three-item tuple
    ``(leaf_count, indices, siblings)`` and each entry the two-item tuple
    ``(index, leaf)``; integers (including out-of-range or negative
    values) carry a sign byte and a shortest big-endian magnitude, tuples
    carry an explicit cardinality and ``bytes`` items are framed raw. The
    function returns ``bytes`` only and never writes to the file system or
    a database.

    Only types are checked: a wrong object or field type (including a
    ``bool`` integer, a non-tuple ``indices``/``siblings``/``entries``
    field or an entry that is not an ``(index, leaf)`` pair) raises
    :class:`TypeError`. A bundle whose proof is semantically inconsistent
    (misordered or duplicate indices, an entries/indices mismatch, an
    out-range index, a non-positive ``leaf_count``) still encodes to
    ``bytes``; those cases are decided by
    :func:`verify_merkle_multi_proof_bundle`.
    """
    if not isinstance(bundle, MerkleMultiProofBundle):
        raise TypeError("bundle must be a MerkleMultiProofBundle")
    if not isinstance(bundle.root, bytes):
        raise TypeError("root must be bytes")
    _check_merkle_multi_bundle_proof_types(bundle.proof)
    _check_merkle_multi_bundle_entries_types(bundle.entries)
    proof = bundle.proof
    proof_body = _wire_tuple(
        [
            _wire_int(proof.leaf_count),
            _wire_tuple([_wire_int(index) for index in proof.indices]),
            _wire_tuple(list(proof.siblings)),
        ]
    )
    entries_body = _wire_tuple(
        [
            _wire_tuple([_wire_int(index), leaf])
            for index, leaf in bundle.entries
        ]
    )
    out = bytearray()
    out += _MERKLE_MULTI_BUNDLE_MAGIC
    out += bytes((_MERKLE_MULTI_BUNDLE_VERSION,))
    out += _wire_frame(bundle.root)
    out += _wire_frame(proof_body)
    out += _wire_frame(entries_body)
    return bytes(out)


def _read_merkle_multi_bundle_proof(reader: _WireReader) -> MerkleMultiProof:
    """Read the framed proof body: ``(leaf_count, indices, siblings)``."""
    body = reader.frame("proof")
    inner = _WireReader(body)
    count = inner.tuple_cardinality("proof")
    if count != 3:
        raise ValueError("proof must have exactly three fields")
    leaf_count = inner.int_value("proof leaf_count")
    indices_body = inner.frame("proof indices")
    indices_reader = _WireReader(indices_body)
    index_count = indices_reader.tuple_cardinality("proof indices")
    indices = tuple(
        indices_reader.int_value(f"proof indices[{position}]")
        for position in range(index_count)
    )
    if not indices_reader.at_end():
        raise ValueError("proof indices tuple has trailing data")
    siblings_body = inner.frame("proof siblings")
    siblings_reader = _WireReader(siblings_body)
    sibling_count = siblings_reader.tuple_cardinality("proof siblings")
    siblings = tuple(
        siblings_reader.frame(f"proof siblings[{position}]")
        for position in range(sibling_count)
    )
    if not siblings_reader.at_end():
        raise ValueError("proof siblings tuple has trailing data")
    if not inner.at_end():
        raise ValueError("proof has trailing data")
    return MerkleMultiProof(
        leaf_count=leaf_count, indices=indices, siblings=siblings
    )


def _read_merkle_multi_bundle_entries(
    reader: _WireReader,
) -> tuple[tuple[int, bytes], ...]:
    """Read the framed entries body: a tuple of ``(index, leaf)`` pairs."""
    body = reader.frame("entries")
    inner = _WireReader(body)
    count = inner.tuple_cardinality("entries")
    entries: list[tuple[int, bytes]] = []
    for position in range(count):
        entry_body = inner.frame(f"entries[{position}]")
        entry_reader = _WireReader(entry_body)
        entry_count = entry_reader.tuple_cardinality(f"entries[{position}]")
        if entry_count != 2:
            raise ValueError(f"entries[{position}] must be an (index, leaf) pair")
        index = entry_reader.int_value(f"entries[{position}] index")
        leaf = entry_reader.frame(f"entries[{position}] leaf")
        if not entry_reader.at_end():
            raise ValueError(f"entries[{position}] has trailing data")
        entries.append((index, leaf))
    if not inner.at_end():
        raise ValueError("entries tuple has trailing data")
    return tuple(entries)


def decode_merkle_multi_proof_bundle(data: bytes) -> MerkleMultiProofBundle:
    """Decode a canonical envelope back into a :class:`MerkleMultiProofBundle`.

    ``data`` must be exactly the output of
    :func:`encode_merkle_multi_proof_bundle`: the magic, a known format
    version, and the three fields in their fixed order with valid length
    prefixes, tuple cardinalities and canonical integers. The payload must
    be consumed completely with no trailing bytes. A truncated input, an
    out-of-bounds length, an unknown version, a non-canonical integer, a
    malformed tuple shape or trailing bytes raises :class:`ValueError`; a
    non-``bytes`` input raises :class:`TypeError`. Decoding checks the
    encoding only: a representable bundle whose proof does not verify
    still decodes successfully, and the decoded bundle compares equal
    field-for-field to the original.
    """
    if not isinstance(data, bytes):
        raise TypeError("data must be bytes")
    reader = _WireReader(data)
    reader.expect(_MERKLE_MULTI_BUNDLE_MAGIC, "merkle multi proof bundle magic")
    version = reader.byte("format version")
    if version != _MERKLE_MULTI_BUNDLE_VERSION:
        raise ValueError("unknown merkle multi proof bundle format version")
    root = reader.frame("root")

